-- insert-zaragoza-centers.sql
-- Inserta los 59 centros de educacion infantil (0-3 anos) de Zaragoza
-- capital investigados y humanizados en este sprint.
-- Fuentes primarias: opendata.aragon.es (GA_OD_Core, Gobierno de Aragon) para el
-- listado base, coordenadas y datos de contacto de centros publicos y privados;
-- zaragoza.es (Patronato Municipal de Educacion y Bibliotecas) para las 13 escuelas
-- infantiles municipales; aragon.es / educa.aragon.es para las 4 escuelas infantiles
-- de titularidad autonomica (Red de Escuelas Infantiles del Gobierno de Aragon);
-- webs propias de centros privados donde se pudo verificar informacion adicional.
-- Ver docs/data-sources-zaragoza.md y data/enrichment/zaragoza-centers.json.
--
-- Ambito: unicamente el termino municipal de Zaragoza capital. Se excluyen
-- explicitamente municipios del area metropolitana (Utebo, Cuarte de Huerva,
-- La Muela, Cuarte, Maria de Huerva, etc.) aunque aparecieran en fuentes
-- provinciales o autonomicas mas amplias.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS
-- hasta cambiarlos a 'published' manualmente tras auditoria, igual que se hizo con
-- Madrid, Barcelona y Valencia).
-- No toca ningun centro de Madrid, Barcelona ni Valencia. No borra ni modifica filas
-- existentes (upsert por slug: si un slug ya existe se actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "zaragoza" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('zaragoza', 'Zaragoza', 'Zaragoza', 'Aragón')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('escuela-infantil-municipal-los-vientos-zaragoza', 'Escuela Infantil Municipal Los Vientos', 'escuela-infantil', 'publico', 'Calle Poeta Luis Cernuda, s/n', '50008', 'zaragoza', 'Zaragoza', NULL, 'Actur-Rey Fernando', NULL, 41.67453286, -0.88303987, '976515750', 'einfantil-vientos@zaragoza.es', NULL, 4, 36, 'De 8:30 a 16:30 h (permanencia máxima de 8 horas por niño/a).', ARRAY['comedor','cocina-propia','escuela-de-padres','patio-exterior','psicomotricidad']::text[], 'Escuela Infantil Municipal Los Vientos, con sede en Calle Poeta Luis Cernuda, s/n, 50008 (barrio de Actur-Rey Fernando), forma parte de la red pública municipal de educación infantil de Zaragoza. Atiende de 4 a 36 meses, dispone de cocina propia para el comedor y organiza actividades de "Escuela de Madres y Padres" durante el curso.', 'Escuela Infantil Municipal Los Vientos es una de las trece escuelas infantiles de la red municipal de Zaragoza, gestionada por el Patronato Municipal de Educación y Bibliotecas del Ayuntamiento, con sede en Calle Poeta Luis Cernuda, s/n, 50008, barrio de Actur-Rey Fernando.

Como el resto de la red municipal, atiende a niños de 4 a 36 meses en horario de 8:30 a 16:30 h, con un máximo de 8 horas de permanencia diaria por niño. La comida se elabora cada día en la cocina propia del centro, con menús adaptados a las distintas edades. Todas las escuelas municipales organizan además actividades de "Escuela de Madres y Padres" para favorecer la participación de las familias en el proceso educativo.

El acceso a una plaza no es automático: se tramita cada curso mediante un proceso de admisión municipal con baremo público (empadronamiento, situación laboral y familiar, entre otros criterios), en un calendario que fija cada año el Patronato Municipal de Educación y Bibliotecas. Para consultas sobre plazas y proceso de solicitud, el centro coordinador de las escuelas infantiles municipales atiende en la calle Cortesías, 1, de 8:30 a 10:00 h.', '{}'::text[], '[{"question":"¿Dónde está ubicado Escuela Infantil Municipal Los Vientos?","answer":"El centro se encuentra en Calle Poeta Luis Cernuda, s/n, 50008, en el barrio de Actur-Rey Fernando, en Zaragoza."},{"question":"¿Qué edades atiende esta escuela infantil municipal?","answer":"Atiende a niños de 4 a 36 meses, dentro del primer ciclo de educación infantil."},{"question":"¿Es un centro público o privado?","answer":"Es un centro público, una de las trece escuelas infantiles municipales gestionadas por el Patronato Municipal de Educación y Bibliotecas del Ayuntamiento de Zaragoza."},{"question":"¿Tiene servicio de comedor?","answer":"Sí. Todas las escuelas infantiles municipales de Zaragoza elaboran la comida en cocina propia, con menús adaptados a cada edad."},{"question":"¿Cómo se solicita una plaza?","answer":"El acceso se tramita mediante el proceso anual de admisión del Ayuntamiento de Zaragoza, con baremo público. Conviene informarse con antelación sobre los plazos de solicitud, habitualmente en primavera."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 976515750 o escribir a einfantil-vientos@zaragoza.es. También puedes dirigirte al Centro Coordinador de Escuelas Infantiles Municipales (C/ Cortesías, 1) en horario de 8:30 a 10:00 h."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www.zaragoza.es/sede/portal/escuelas-infantiles/centros', ARRAY['https://www.zaragoza.es/contenidos/educacionybibliotecas/Guia_uso_esc_inf_08.pdf']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
